#!/usr/bin/env python3
r"""Precompute translated A_down table with phi integration.

Goal:
- Build grids with user-requested ranges:
  omega in [-20, 20], p in [0, 6]
- For each omega/p/eps, evaluate
    A_down(|q-p|_phi, omega-eps)
  on a phi grid and precompute phi-integrated table:
    A_down_phi_int(omega,p,eps) = \int_0^{2pi} dphi A_down(...)

This is useful when the integrand has A_up(p,eps) * A_down(...),
because A_up is phi-independent and phi can be absorbed into this table.
"""

from __future__ import annotations

import argparse
import os
from datetime import datetime
from pathlib import Path

import numpy as np


REPO_ROOT = Path(__file__).resolve().parents[1]

